<template>
  <section aria-label="qSOFA原资料登记与选择">
    <p v-if="!allowed">请先选择有权限的患者、原住院及冻结观测窗。</p>
    <template v-else>
      <p>患者 #{{ patientId }} · 原住院 {{ admissionId }} · 原窗 {{ windowId }}。明确选择单一原点和可选同次原GCS；不从AVPU换算，不自动拼接或取最近值。</p>
      <el-select v-model="selectedId" aria-label="待计算qSOFA评估来源" clearable :disabled="loading || checking || creating || revoking" placeholder="明确选择已登记原评估"><el-option v-for="row in sources" :key="row.assessment_id" :value="row.assessment_id" :disabled="row.status !== 'active' || row.eligible !== true" :label="`${row.evaluation_at} · ${row.assessment_id} · ${row.status === 'active' ? '活动来源' : '已撤销'}`" /></el-select><el-button :loading="loading" :disabled="creating || revoking" @click="loadSources">刷新qSOFA评估目录</el-button><p>原窗目录共 {{ total ?? '未知' }} 项；登记有效不证明资料齐全或临床效果已验证。</p><el-pagination v-if="total > 50" v-model:current-page="page" :page-size="50" :total="total" layout="prev,pager,next" @current-change="loadSources" />
      <p v-if="error" role="alert">{{ error }}</p><p v-if="notice">{{ notice }}</p>
      <template v-if="selected"><p>已核对 {{ selected.assessment_id }} · {{ selected.content_hash }}；当前回顾声明 {{ selected.evaluation_at }}。</p><el-button @click="detailOpen = true">核对所选qSOFA原来源</el-button><template v-if="selected.can_revoke === true"><el-input v-model="revokeReason" aria-label="qSOFA来源撤销依据" maxlength="1000" /><el-button type="danger" :loading="revoking" :disabled="revokeReason.trim().length < 5" @click="revoke">撤销所选qSOFA评估</el-button></template></template>
      <el-collapse><el-collapse-item title="登记qSOFA当前回顾评估来源">
        <el-button :loading="candidateLoading" :disabled="creating" @click="loadCandidates">读取qSOFA原点、GCS与审核规则</el-button><p v-if="!canSign">当前回执未授予实际临床签署资格；护士可选择已有有效评估，管理身份不代替医生与当前照护关系。</p>
        <el-form label-position="top" :disabled="creating || !canSign" @submit.prevent>
          <el-form-item label="明确单一原点"><el-select v-model="pointId" aria-label="qSOFA明确原点测" clearable placeholder="不自动选最近、最高或最低值"><el-option v-for="row in points" :key="row.observation_id" :value="row.observation_id" :label="`${row.observed_at} · ${row.observation_id}`" /></el-select></el-form-item><el-form-item label="独立固定规则审核版本"><el-select v-model="profileId" aria-label="qSOFA审核规则版本" clearable placeholder="明确选择已发布Sepsis-3 qSOFA实现"><el-option v-for="row in profiles" :key="row.rule_profile_id" :value="row.rule_profile_id" :label="`${row.name} · ${row.rule_id} · v${row.revision}`" /></el-select></el-form-item>
          <p v-if="point">所选原点实际观察 {{ point.observed_at }}；原登记 {{ point.recorded_at }}。RR {{ point.payload.measurements.respiratory_rate?.value ?? '未测' }} /min；SBP {{ point.payload.measurements.systolic_bp?.value ?? '未测' }} mm[Hg]。0是原量，不表示正常。</p>
          <el-form-item label="原观察时年龄核实状态"><el-select v-model="form.ageMode" aria-label="qSOFA年龄核实状态" placeholder="明确选择，不从今天推算"><el-option label="有明确原年龄" value="known" /><el-option label="原年龄未知" value="unknown" /></el-select></el-form-item><el-input v-if="form.ageMode === 'known'" v-model="form.age" aria-label="qSOFA原观察时年龄" inputmode="numeric" placeholder="明确原年龄0至130整岁" /><el-input v-model="form.age_basis_note" aria-label="qSOFA原年龄依据" type="textarea" maxlength="1000" placeholder="至少20字，记录原年龄或无法核实的依据" />
          <el-form-item label="所选原点实际场景"><el-select v-model="form.care_setting" aria-label="qSOFA原场景声明" placeholder="明确核实，不从科室名推断"><el-option label="已核实非ICU" value="non_icu" /><el-option label="ICU" value="icu" /><el-option label="未知" value="unknown" /></el-select></el-form-item><el-input v-model="form.care_setting_basis_note" aria-label="qSOFA原场景依据" type="textarea" maxlength="1000" placeholder="至少20字，记录原时点实际场景依据" />
          <el-form-item label="所选原点感染临床状态"><el-select v-model="form.infection_status" aria-label="qSOFA原感染声明" placeholder="明确临床核实，不从药单或培养自动推定"><el-option label="疑似感染" value="suspected" /><el-option label="已知感染" value="documented" /><el-option label="未疑似感染" value="not_suspected" /><el-option label="未知" value="unknown" /></el-select></el-form-item><el-input v-model="form.infection_basis_note" aria-label="qSOFA原感染依据" type="textarea" maxlength="1000" placeholder="至少20字，记录原时点临床状态核实依据" />
          <el-form-item label="明确同次原GCS（可选）"><el-select v-model="form.gcsId" aria-label="qSOFA明确原GCS" clearable :disabled="!point" placeholder="不自动最近；不选则意识项未知"><el-option v-for="row in gcsOptions" :key="row.gcs_observation_id" :value="row.gcs_observation_id" :label="`${row.observed_at} · E${part(row,'eye')} V${part(row,'verbal')} M${part(row,'motor')} · ${row.gcs_observation_id}`" /></el-select></el-form-item>
          <template v-if="form.gcsId"><p v-if="chosenGcs">GCS原实际观察 {{ chosenGcs.observed_at }}；原登记 {{ chosenGcs.recorded_at }}。与原点属于人工明确同次检查，两个实际UTC可以不同，不改写为相等。</p><el-form-item label="GCS临床可判读核实"><el-select v-model="form.gcs_interpretability" aria-label="qSOFA GCS可判读声明" placeholder="明确核实镇静、插管、语言或既存障碍等限制"><el-option label="明确可判读" value="confirmed" /><el-option label="受限" value="limited" /><el-option label="未知" value="unknown" /></el-select></el-form-item><el-input v-model="form.gcs_review_note" aria-label="qSOFA GCS判读依据" type="textarea" maxlength="1000" placeholder="至少20字，NT或受限不能补正常总分，不指示停药或唤醒" /></template>
          <p>登记时刻由服务器记录当前临床回顾，可能晚于原窗as_of；不冒称这些临床声明在旧截止时已知，不提供历史预测。未成年人、ICU或未疑似感染可保留原事实，但不提供目标人群计数。</p><p v-if="formError" role="alert">{{ formError }}</p><el-button type="primary" :disabled="!canCreate" :loading="creating" @click="create">仅登记qSOFA评估来源</el-button>
        </el-form>
      </el-collapse-item></el-collapse>
    </template>
    <el-dialog v-model="detailOpen" title="qSOFA原评估来源核对" width="min(1050px,96vw)"><ai-qsofa-findings v-if="allowed && selected" :source="selected.specialist_source" :scope="selected" :expected-patient-id="patientId" :expected-admission-id="admissionId" /></el-dialog>
  </section>
</template>
<script setup>
import { computed, onActivated, onBeforeUnmount, onDeactivated, ref, watch } from "vue";
import { useStore } from "vuex";
import AiQsofaFindings from "@/components/AIQsofaFindings/index.vue";
import { createQsofaAssessment, getQsofaAssessment, getQsofaAssessments, getQsofaCandidates, qsofaAssessmentMatches, qsofaCanonical, revokeQsofaAssessment } from "@/api/aiQsofa";
import { gcsAbsentLabels, gcsHash, gcsObservationMatches } from "@/api/inpatientGcs";
const props = defineProps({ patientId: { type: Number, required: true }, admissionId: { type: String, required: true }, windowId: { type: String, required: true }, active: { type: Boolean, default: true } }), emit = defineEmits(["selection", "availability"]), store = useStore();
const roles = computed(() => store.getters["user/permissions"] || []), allowed = computed(() => props.active && !!store.state.user.accessToken && Number.isSafeInteger(props.patientId) && props.patientId > 0 && !!props.admissionId && !!props.windowId && roles.value.some(role => ["nurse", "doctor", "director", "admin", "super_admin"].includes(role)));
const blank = () => ({ ageMode: "", age: "", age_basis_note: "", care_setting: "", care_setting_basis_note: "", infection_status: "", infection_basis_note: "", gcsId: "", gcs_interpretability: "", gcs_review_note: "" });
const form=ref(blank()),pointId=ref(""),profileId=ref(""),points=ref([]),profiles=ref([]),gcsItems=ref([]),sources=ref([]),page=ref(1),total=ref(null),selectedId=ref(""),selected=ref(null),loading=ref(false),checking=ref(false),candidateLoading=ref(false),creating=ref(false),revoking=ref(false),canSignReply=ref(false),windowHash=ref(""),error=ref(""),notice=ref(""),detailOpen=ref(false),revokeReason=ref("");
let epoch=0,listSequence=0,candidateSequence=0,detailSequence=0,inactive=false;
const scopeKey=()=>JSON.stringify([props.patientId,props.admissionId,props.windowId,props.active,store.state.user.accessToken,roles.value]),capture=()=>({epoch,key:scopeKey(),patientId:props.patientId,admissionId:props.admissionId,windowId:props.windowId}),current=ticket=>ticket.epoch===epoch && ticket.key===scopeKey() && allowed.value && !inactive,query=ticket=>({patient_id:ticket.patientId,admission_id:ticket.admissionId,window_id:ticket.windowId});
const point=computed(()=>points.value.find(row=>row.observation_id===pointId.value)),profile=computed(()=>profiles.value.find(row=>row.rule_profile_id===profileId.value)),canSign=computed(()=>canSignReply.value && roles.value.some(role=>["doctor","director","super_admin"].includes(role)));
const gcsOptions=computed(()=>gcsItems.value.filter(row=>row.status==="active" && row.anchor_current===true && row.payload.anchor_point?.observation_id===pointId.value && row.payload.anchor_point?.expected_content_hash===point.value?.content_hash)),chosenGcs=computed(()=>gcsOptions.value.find(row=>row.gcs_observation_id===form.value.gcsId));
const part=(row,key)=>row.payload.components[key].score ?? gcsAbsentLabels[row.payload.components[key].absent_reason];
function payload(){const draft=form.value,ticket=capture();if(!canSign.value || !point.value || !profile.value || !windowHash.value)throw new Error("先明确原点、已发布独立规则与实际临床签署资格");if(!["known","unknown"].includes(draft.ageMode) || (draft.ageMode==="known" && (!/^(?:0|[1-9]\d{0,2})$/.test(draft.age) || Number(draft.age)>130)))throw new Error("原年龄须明确合法整岁或选择未知，不补0");if(!["non_icu","icu","unknown"].includes(draft.care_setting) || !["suspected","documented","not_suspected","unknown"].includes(draft.infection_status) || [draft.age_basis_note,draft.care_setting_basis_note,draft.infection_basis_note].some(text=>text.trim().length<20))throw new Error("原年龄、场景及感染须明确声明并分别填写至少20字原依据");const gcs=chosenGcs.value;if(draft.gcsId && (!gcs || !["confirmed","limited","unknown"].includes(draft.gcs_interpretability) || draft.gcs_review_note.trim().length<20))throw new Error("所选原GCS须明确原关联、可判读状态与至少20字临床核实依据");return {...query(ticket),expected_window_hash:windowHash.value,point_id:point.value.observation_id,expected_point_hash:point.value.content_hash,rule_profile_id:profile.value.rule_profile_id,expected_rule_profile_hash:profile.value.content_hash,age_at_observation_years:draft.ageMode==="known"?Number(draft.age):null,age_basis_note:draft.age_basis_note.trim(),care_setting:draft.care_setting,care_setting_basis_note:draft.care_setting_basis_note.trim(),infection_status:draft.infection_status,infection_basis_note:draft.infection_basis_note.trim(),gcs_observation:gcs?{gcs_observation_id:gcs.gcs_observation_id,expected_content_hash:gcs.content_hash}:null,gcs_interpretability:gcs?draft.gcs_interpretability:"unknown",gcs_review_note:gcs?draft.gcs_review_note.trim():null};}
const formError=computed(()=>{try{payload();return "";}catch(failure){return failure.message;}}),canCreate=computed(()=>allowed.value && !creating.value && !formError.value);
function clearSelection(){detailSequence++;selectedId.value="";selected.value=null;checking.value=false;detailOpen.value=false;revokeReason.value="";emit("selection",null);emit("availability",false);}
function clearDraft(){pointId.value="";profileId.value="";form.value=blank();}
function reset(){epoch++;listSequence++;candidateSequence++;clearSelection();clearDraft();points.value=[];profiles.value=[];gcsItems.value=[];sources.value=[];page.value=1;total.value=null;canSignReply.value=false;windowHash.value="";loading.value=checking.value=candidateLoading.value=creating.value=revoking.value=false;error.value=notice.value="";}
async function loadSources(){clearSelection();if(!allowed.value || inactive)return;const ticket=capture(),seq=++listSequence;loading.value=true;sources.value=[];error.value="";try{const res=await getQsofaAssessments({...query(ticket),page:page.value,page_size:50});if(!current(ticket)||seq!==listSequence)return;if(!Array.isArray(res.data?.items)||res.data.items.some(row=>!qsofaAssessmentMatches(row,ticket.patientId,ticket.admissionId,ticket.windowId)))throw new Error("qSOFA目录与原患者、住院或窗口不一致");sources.value=res.data.items;total.value=res.data.total;}catch(failure){if(current(ticket)&&seq===listSequence)error.value=failure?.message||"qSOFA目录未能读取";}finally{if(current(ticket)&&seq===listSequence)loading.value=false;}}
async function loadCandidates(){if(!allowed.value||inactive||creating.value)return;clearDraft();points.value=[];profiles.value=[];gcsItems.value=[];windowHash.value="";canSignReply.value=false;const ticket=capture(),seq=++candidateSequence;candidateLoading.value=true;error.value="";try{const res=await getQsofaCandidates(query(ticket));if(!current(ticket)||seq!==candidateSequence)return;const data=res.data,window=data?.window;if(window?.patient_id!==ticket.patientId||window.admission_id!==ticket.admissionId||window.window_id!==ticket.windowId||!gcsHash(window.content_hash)||!Array.isArray(data.points)||data.points.some(row=>row.patient_id!==ticket.patientId||row.admission_id!==ticket.admissionId||row.status!=="active"||!gcsHash(row.content_hash))||!Array.isArray(data.gcs_observations)||data.gcs_observations.some(row=>!gcsObservationMatches(row,ticket.patientId,ticket.admissionId))||!Array.isArray(data.rule_profiles))throw new Error("qSOFA原点、GCS、规则或窗口回执不符合原范围");points.value=data.points;gcsItems.value=data.gcs_observations;profiles.value=data.rule_profiles.filter(row=>row.rule_id==="qsofa_sepsis3_2016"&&row.status==="published"&&row.revision===2&&gcsHash(row.content_hash));windowHash.value=window.content_hash;canSignReply.value=data.can_sign_clinical===true;}catch(failure){if(current(ticket)&&seq===candidateSequence)error.value=failure?.message||"qSOFA原资料未能读取";}finally{if(current(ticket)&&seq===candidateSequence)candidateLoading.value=false;}}
async function create(){if(!canCreate.value||inactive)return;const ticket=capture(),body=payload();clearSelection();creating.value=true;try{const res=await createQsofaAssessment(body);if(!current(ticket))return;const row=res.data;if(!qsofaAssessmentMatches(row,ticket.patientId,ticket.admissionId,ticket.windowId,true)||row.window_content_hash!==body.expected_window_hash||row.point_id!==body.point_id||row.point_content_hash!==body.expected_point_hash||row.rule_profile_id!==body.rule_profile_id||row.rule_profile_content_hash!==body.expected_rule_profile_hash||row.status!=="active"||row.revision!==1||qsofaCanonical(row.snapshot.attestation)!==qsofaCanonical(body))throw new Error("qSOFA登记回执与原引用或当前临床声明不一致");clearDraft();page.value=1;await loadSources();if(current(ticket))notice.value="qSOFA当前回顾来源已登记；请明确选择并核对，尚未调用规则服务或自动计数。";}catch(failure){if(current(ticket))error.value=failure?.message||"qSOFA来源登记失败";}finally{if(current(ticket))creating.value=false;}}
async function revoke(){if(!allowed.value||inactive||selected.value?.can_revoke!==true||revokeReason.value.trim().length<5||revoking.value)return;const ticket=capture(),original=selected.value,reason=revokeReason.value.trim();clearSelection();revoking.value=true;try{const res=await revokeQsofaAssessment(original.assessment_id,{patient_id:ticket.patientId,admission_id:ticket.admissionId,expected_revision:original.revision,reason});if(!current(ticket))return;if(!qsofaAssessmentMatches(res.data,ticket.patientId,ticket.admissionId,ticket.windowId)||res.data.assessment_id!==original.assessment_id||res.data.content_hash!==original.content_hash||res.data.status!=="revoked"||res.data.revision!==original.revision+1)throw new Error("qSOFA撤销回执与原评估版本不一致");await loadSources();if(current(ticket))notice.value="qSOFA原评估已撤销；旧选择不能继续计算，请重新核实来源。";}catch(failure){if(current(ticket))error.value=failure?.message||"qSOFA撤销失败";}finally{if(current(ticket))revoking.value=false;}}
watch(selectedId,async id=>{const ticket=capture(),seq=++detailSequence;selected.value=null;emit("selection",null);emit("availability",false);error.value="";if(!id||!allowed.value||inactive)return;checking.value=true;try{const res=await getQsofaAssessment(id,{patient_id:ticket.patientId,admission_id:ticket.admissionId});if(!current(ticket)||seq!==detailSequence||selectedId.value!==id)return;const row=res.data;if(!qsofaAssessmentMatches(row,ticket.patientId,ticket.admissionId,ticket.windowId,true)||row.assessment_id!==id||row.status!=="active"||row.revision!==1||row.eligible!==true||row.freshness?.state!=="current")throw new Error("qSOFA原评估、临床声明或点/GCS/规则已变化，不能作为当前计算来源");selected.value=row;emit("selection",{qsofa_assessment_id:row.assessment_id,content_hash:row.content_hash});emit("availability",true);}catch(failure){if(current(ticket)&&seq===detailSequence)error.value=failure?.message||"qSOFA所选来源未能核对";}finally{if(current(ticket)&&seq===detailSequence)checking.value=false;}});
watch([pointId,profileId],()=>{form.value=blank();},{flush:"sync"});watch(()=>form.value.gcsId,()=>{form.value.gcs_interpretability="";form.value.gcs_review_note="";},{flush:"sync"});watch(scopeKey,()=>{reset();loadSources();},{immediate:true,flush:"sync"});onDeactivated(()=>{inactive=true;reset();});onActivated(()=>{if(inactive){inactive=false;reset();loadSources();}});onBeforeUnmount(()=>{inactive=true;reset();});
</script>
<style scoped>p{line-height:1.7;overflow-wrap:anywhere;}.el-select{width:100%;}.el-button{margin:8px 8px 8px 0;}.el-checkbox{white-space:normal;}</style>
